def populate_project_slugs(apps, schema_editor):
    from django.utils.text import slugify
    Project = apps.get_model("blog", "Project")
    used = set()
    for project in Project.objects.order_by("id"):
        base = (slugify(project.title) or f"project-{project.pk}")[:200]
        slug, n = base, 2
        while slug in used:
            slug = f"{base}-{n}"
            n += 1
        used.add(slug)
        project.slug = slug
        project.save(update_fields=["slug"])


